; mul.asm -- chapter 10: eight bits times eight
; generated by gen10.py
        INCLUDE "msx.inc"
        OUTPUT "mul.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
init:   di
        ld sp, SYS_AREA
second  EQU RAM_START          ; the second number
total   EQU RAM_START + 1      ; 32 bits: the sum of all the products
check   EQU RAM_START + 5      ; 16 bits: the products mixed with XOR
prod    EQU RAM_START + 7      ; the timed products, two bytes each
        xor a
        ld hl, total
        ld b, 6
clr:    ld (hl), a
        inc hl
        djnz clr                ; total and check start at 0
        ld h, $00
        ld e, $C8
m0:     call mul8               ; $00 x $C8
        ld (prod+0), hl
        ld h, $01
        ld e, $C8
m1:     call mul8               ; $01 x $C8
        ld (prod+2), hl
        ld h, $55
        ld e, $C8
m2:     call mul8               ; $55 x $C8
        ld (prod+4), hl
        ld h, $FF
        ld e, $C8
m3:     call mul8               ; $FF x $C8
        ld (prod+6), hl
        ld c, 0                 ; C: the first number, 0 to 255
outer:  xor a
        ld (second), a
inner:  ld h, c
        ld a, (second)
        ld e, a
        call mul8               ; HL = C x the second number
        call tally
        ld a, (second)
        inc a
        ld (second), a
        jr nz, inner            ; all 256 second numbers
        inc c
        jr nz, outer            ; for all 256 first numbers
stop:   jr stop

; mul8: HL = H x E, both taken as unsigned. Uses B and D.
mul8:   ld d, 0                 ; DE = E, sixteen bits wide
        ld l, d                 ; HL = H x 256: H is the multiplier
        ld b, 8
ml1:    add hl, hl              ; the result doubles, and the top bit
        jr nc, ml2              ; of the multiplier falls into the carry
        add hl, de              ; a 1: add E once more
ml2:    djnz ml1
        ret

; tally: the product in HL added into total (32 bits, low byte first) and
;        mixed into check (16 bits) with XOR
tally:  ex de, hl               ; DE = the product
        ld hl, (total)
        add hl, de
        ld (total), hl          ; the low sixteen bits
        jr nc, ty1
        ld hl, (total + 2)
        inc hl
        ld (total + 2), hl      ; and the carry into the high sixteen
ty1:    ld a, (check)
        xor e
        ld (check), a
        ld a, (check + 1)
        xor d
        ld (check + 1), a
        ret
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
